window.ScripturaLexicons.BDAG_PART_0187 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-01\" data-source=\"BDAG\" data-search=\"κάρφος, ους, τό substantivo neutro argueiro; cisco; lasca BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάρφος, ους, τό</td><td>substantivo neutro</td><td>argueiro; cisco; lasca</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-02\" data-source=\"BDAG\" data-search=\"καρχηδών remissão lexical veja χαλκηδών BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καρχηδών</td><td>remissão lexical</td><td>veja χαλκηδών</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-03\" data-source=\"BDAG\" data-search=\"κατά preposição de; por; contra; segundo; em BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατά</td><td>preposição</td><td>de; por; contra; segundo; em</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-04\" data-source=\"BDAG\" data-search=\"καταβαίνω verbo descer; vir de cima BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταβαίνω</td><td>verbo</td><td>descer; vir de cima</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-05\" data-source=\"BDAG\" data-search=\"καταβάλλω verbo derrubar; lançar os fundamentos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταβάλλω</td><td>verbo</td><td>derrubar; lançar os fundamentos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-06\" data-source=\"BDAG\" data-search=\"καταβαρέω verbo sobrecarregar; pesar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταβαρέω</td><td>verbo</td><td>sobrecarregar; pesar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-07\" data-source=\"BDAG\" data-search=\"καταβαρύνω verbo oprimir; sobrecarregar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταβαρύνω</td><td>verbo</td><td>oprimir; sobrecarregar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-08\" data-source=\"BDAG\" data-search=\"κατάβασις, εως, ἡ substantivo feminino descida; encosta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατάβασις, εως, ἡ</td><td>substantivo feminino</td><td>descida; encosta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-09\" data-source=\"BDAG\" data-search=\"καταβῇ remissão lexical veja καταβαίνω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταβῇ</td><td>remissão lexical</td><td>veja καταβαίνω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-10\" data-source=\"BDAG\" data-search=\"καταβιβάζω verbo fazer descer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταβιβάζω</td><td>verbo</td><td>fazer descer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-11\" data-source=\"BDAG\" data-search=\"καταβοάω verbo clamar; acusar; queixar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταβοάω</td><td>verbo</td><td>clamar; acusar; queixar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-12\" data-source=\"BDAG\" data-search=\"καταβολή, ῆς, ἡ substantivo feminino fundação; começo; concepção BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταβολή, ῆς, ἡ</td><td>substantivo feminino</td><td>fundação; começo; concepção</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-13\" data-source=\"BDAG\" data-search=\"καταβραβεύω verbo privar de prêmio; condenar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταβραβεύω</td><td>verbo</td><td>privar de prêmio; condenar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-14\" data-source=\"BDAG\" data-search=\"καταγγελεύς, έως, ὁ substantivo masculino anunciador; pregador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταγγελεύς, έως, ὁ</td><td>substantivo masculino</td><td>anunciador; pregador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-15\" data-source=\"BDAG\" data-search=\"καταγγέλλω verbo proclamar; anunciar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταγγέλλω</td><td>verbo</td><td>proclamar; anunciar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-16\" data-source=\"BDAG\" data-search=\"καταγέλαστος, ον adjetivo ridículo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταγέλαστος, ον</td><td>adjetivo</td><td>ridículo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-17\" data-source=\"BDAG\" data-search=\"καταγελάω verbo ridicularizar; zombar de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταγελάω</td><td>verbo</td><td>ridicularizar; zombar de</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-18\" data-source=\"BDAG\" data-search=\"καταγίνομαι verbo ocupar-se de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταγίνομαι</td><td>verbo</td><td>ocupar-se de</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-19\" data-source=\"BDAG\" data-search=\"καταγινώσκω verbo condenar; declarar culpado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταγινώσκω</td><td>verbo</td><td>condenar; declarar culpado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0187-20\" data-source=\"BDAG\" data-search=\"κατάγνυμι verbo quebrar; despedaçar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατάγνυμι</td><td>verbo</td><td>quebrar; despedaçar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0187-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάρφος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ésquilo, Heródoto e outros; Gen 8:11) pequeno fragmento de palha, restolho ou madeira, indicando algo insignificante: argueiro, lasca, cisco (cf. o provérbio <span class=\"greek\">κινεῖν μηδὲ κ</span>. Aristoph., Lysias 474 e Herodas 1, 54; 3, 67.—Íon de Quios [século V a.C.]: 392 Fgm. 6 p. 280, 7 Jac. referente a um corpúsculo estranho numa taça de vinho. Inscrição funerária, Kaibel 980, 9 [<span class=\"greek\">ὁ εὐσεβὴς</span>] <span class=\"greek\">οὐδὲ κάρφος ἐβλάβη</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:3f</a>f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:41f</a>; Ox 1 verso, 2 (ASyn. 68, 44)=GTh 26.—Quanto à bibliografia, veja <span class=\"greek\">δοκός</span>.—DELG sob o verbete <span class=\"greek\">κάρφω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καρχηδών</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">veja <span class=\"greek\">χαλκηδών</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατά</h1><div class=\"entry-meta\"><span>preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(desde Homero) preposição (quanto à bibliografia, veja sob <span class=\"greek\">ἀνά</span>, no início, e LfgrE sob <span class=\"greek\">κατά</span>, 1346; com genitivo 74 vezes no NT; com acusativo 391 vezes no NT).</p><p class=\"entry-text\"> A. Com genitivo</p><p class=\"entry-text\"> ① indicador de extensão ou orientação no espaço ou em uma área específica</p><p class=\"entry-text\"> ⓐ referente a uma posição relativamente inferior: para baixo a partir de alguma coisa (Homero e outros; LXX; Ath. 1, 4 <span class=\"greek\">κ</span>. <span class=\"greek\">κόρρης προπηλακίζειν</span>=dar uma bofetada num lado da cabeça) <span class=\"greek\">ὁρμᾶν κ</span>. <span class=\"greek\">τοῦ κρημνοῦ</span> precipitar-se barranco abaixo (cf. Polyb. 38, 16, 7 <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν κρημνῶν ῥίπτειν</span>; Jos., Bell. 1, 313) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:33</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">κεφαλῆς ἔχειν</span> ter alguma coisa sobre a cabeça (literalmente, pendendo da cabeça como um véu. Cf. Plutarco, Mor. 200f <span class=\"greek\">ἐβάδιζε κ</span>. <span class=\"greek\">τῆς κεφαλῆς ἔχων τὸ ἱμάτιον</span>.; Mitt-Wilck. I/2, 499, 5 a respeito de uma múmia <span class=\"greek\">ἔχων τάβλαν κ</span>. <span class=\"greek\">τοῦ τραχήλου</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:4</a>.</p><p class=\"entry-text\"> ⓑ referente a uma posição em profundidade: para dentro de alguma coisa (Od. 9, 330 <span class=\"greek\">κ</span>. <span class=\"greek\">σπείους</span> «para as profundezas da caverna»; Hdt. 7, 235; X., An. 7, 1, 30) <span class=\"greek\">ἡ κ</span>. <span class=\"greek\">βάθους πτωχεία</span> extrema (literalmente, «chegando até as profundezas»; cf. Strabo 9, 3, 5 [419] <span class=\"greek\">ἄντρον κοῖλον κ</span>. <span class=\"greek\">βάθους</span>) ou pobreza abissal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:2</a>. Talvez seja esta a acepção de <span class=\"greek\">πλήσσειν τινὰ κ</span>. <span class=\"greek\">τῶν ὀφθαλμῶν</span> golpear alguém profundamente nos olhos ApcPt 11:26 (cf. Demosth. 19, 197 <span class=\"greek\">ξαίνει κ</span>. <span class=\"greek\">τοῦ νώτου</span>; PPetr II, 18 [2b], 15 [246 a.C.] <span class=\"greek\">ἔτυπτεν αὐτὸν κ</span>. <span class=\"greek\">τοῦ τραχήλου</span>).—<span class=\"greek\">κ</span>. <span class=\"greek\">γαστρός</span> Just., D. 78, 3 em lugar de <span class=\"greek\">ἐν γαστρί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:18</a> (cf. Ath. 35, 2 <span class=\"greek\">τὸ κ</span>. <span class=\"greek\">γαστρὸς ζῶον εἶναι</span>).</p><p class=\"entry-text\"> ⓒ extensão em diversas direções dentro de uma área: por toda parte, ao longo de (assim nos escritos de Lucas; Polyb. 3, 19, 7 <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς νήσου διεσπάρησαν</span>; PGiss 48, 8 <span class=\"greek\">κ</span>. <span class=\"greek\">κυριακῆς γῆς</span>; Jos., Ant. 8, 297; SibOr 3, 222; 4, 24; 5, 305) <span class=\"greek\">γνωστὸν γενέσθαι καθ</span>’ <span class=\"greek\">ὅλης Ἰόππης</span> tornar-se conhecido por toda Jope <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:42</a>. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὅλης τῆς Ἰουδαίας</span> 9:31; 10:37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:5</a>. <span class=\"greek\">φήμη ἐξῆλθεν καθ</span>’ <span class=\"greek\">ὅλης τῆς περιχώρου</span> 4:14.</p><p class=\"entry-text\"> ② sobre, em direção a ou contra alguém ou alguma coisa; extensão figurada da acepção 1.</p><p class=\"entry-text\"> ⓐ com verbos de juramento, indicando por quem ou pelo que se jura (Thu. 5, 47, 8; Lysias 32, 13; Isaeus 7, 28; Demosth. 21, 119; 29, 26; SIG 526, 4ff; 685, 25; UPZ 110, 39 [164 a.C.]; BGU 248, 13; Jdth 1:12; Is 45:23; 2 Ch 36:13) por, com <span class=\"greek\">ἐξορκίζειν</span> (veja o verbete) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.63\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:63</a>. <span class=\"greek\">ὀμνύναι</span> (veja o verbete) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:13</a>, 16. <span class=\"greek\">ὁρκίζειν</span> (veja o verbete) Hs 9, 10, 5. Semelhantemente, <span class=\"greek\">ἐρωτᾶν κ</span>. <span class=\"greek\">τινος</span>, pedir ou suplicar por alguém Hv 3, 2, 3.</p><p class=\"entry-text\"> ⓑ em sentido hostil: contra</p><p class=\"entry-text\"> <span class=\"greek\">α</span>. após verbos que expressam ação hostil etc. <span class=\"greek\">διχάζειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:35</a>. <span class=\"greek\">ἐπαίρεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:5</a>. <span class=\"greek\">ἰσχύειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:16</a>. <span class=\"greek\">κακοῦν</span> 14:2. <span class=\"greek\">στρατεύεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:11</a>. <span class=\"greek\">φυσιοῦσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:6</a></p><p class=\"entry-text\"> <span class=\"greek\">β</span>. após palavras e expressões que designam discurso hostil, especialmente uma acusação <span class=\"greek\">ἔχειν</span> (<span class=\"greek\">τι</span>) <span class=\"greek\">κ</span>. <span class=\"greek\">τινος</span> ter ou sustentar alguma coisa contra alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:4</a>, 14, 20. <span class=\"greek\">φέρειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:29</a>. <span class=\"greek\">ἐγκαλεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:33</a>. <span class=\"greek\">ἐντυγχάνειν τινὶ κ</span>. <span class=\"greek\">τινος</span> 11:2 (TestJob 17:5). <span class=\"greek\">κατηγορεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:14</a>. <span class=\"greek\">ποιεῖν κρίσιν</span> Jd 15a. <span class=\"greek\">τὸ κ</span>. <span class=\"greek\">ἡμῶν χειρόγραφον</span> o escrito de dívida que nos é contrário <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:14</a>. <span class=\"greek\">ἐμφανίζειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:1</a>; 25:2. <span class=\"greek\">αἰτεῖσθαί τι</span> 25:3, 15. <span class=\"greek\">αἱ κ</span>. <span class=\"greek\">τινος αἰτίαι</span> vs. 27. <span class=\"greek\">εἰπεῖν πονηρόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:11</a> (cf. Soph., Phil. 65 <span class=\"greek\">κακὰ λέγειν κ</span>. <span class=\"greek\">τινος</span>. X., Hell. 1, 5, 2; Isocr., C. Nic. 13; Plut., Mor. 2a <span class=\"greek\">λέγειν κ</span>.; SIG 1180, 1 <span class=\"greek\">λέγειν κ</span>. <span class=\"greek\">τινος</span>; Just., A I, 23, 3; 49, 6 <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> … <span class=\"greek\">ὁμολογούντων</span>). <span class=\"greek\">λαλεῖν ῥήματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:13</a>; cf. Jd 15b (TestDan 4:3; JosAs 23:15). <span class=\"greek\">μαρτυρεῖν κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> dar testemunho contrário a Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:15</a>. <span class=\"greek\">ζητεῖν μαρτυρίαν κ</span>. <span class=\"greek\">τινος</span> testemunho contra alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:55</a>. <span class=\"greek\">ψευδομαρτυρεῖν</span> 14:56f. <span class=\"greek\">ψευδομαρτυρία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.59\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:59</a>. <span class=\"greek\">γογγύζειν</span> 20:11. <span class=\"greek\">στενάζειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:9</a>. <span class=\"greek\">διδάσκειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:28</a>. <span class=\"greek\">συμβούλιον διδόναι</span> (<span class=\"greek\">ποιεῖν</span> v.l.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:6</a>; <span class=\"greek\">ς</span>. <span class=\"greek\">λαβεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:1</a>. <span class=\"greek\">ψεύδεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:14</a> (Lysias 22, 7; X., Ap. 13; Ath. 35, 1 <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμῶν</span> … <span class=\"greek\">κατεψεύσατο</span>).</p><p class=\"entry-text\"> <span class=\"greek\">γ</span>. após expressões que designam tal posição ou disposição de outro modo <span class=\"greek\">εἶναι κ</span>. <span class=\"greek\">τινος</span> estar contra alguém (em oposição a <span class=\"greek\">ὑπέρ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:40</a> (WNestle, ZNW 13, 1912, 84–87; AFridrichsen, ibid., 273–80); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:31</a>; (em oposição a <span class=\"greek\">μετά</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:23</a>. <span class=\"greek\">δύνασθαί τι κ</span>. <span class=\"greek\">τινος</span> poder fazer alguma coisa contra alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:8</a>. <span class=\"greek\">ἔχειν τι κ</span>. <span class=\"greek\">τινος</span> ter algo contra alguém (no coração) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:25</a>; Hs 9, 24, 2; cf. ibid. 23, 2, em que se deve subentender o acusativo. <span class=\"greek\">ἐξουσίαν ἔχειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:11</a>. <span class=\"greek\">ἐπιθυμεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:17</a>. <span class=\"greek\">μερίζεσθαι καθ</span>’ <span class=\"greek\">ἑαυτῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:25</a>. Cf. 1 Cl 39:4 (Job 4:18).—<span class=\"greek\">κατά</span> provavelmente também significa «contra» em <span class=\"greek\">ἔβαλεν κατ</span>’ <span class=\"greek\">αὐτῆς ἄνεμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:14</a>. <span class=\"greek\">ἐτελείωσαν κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">κεφαλῆς αὐτῶν τὰ ἁμαρτήματα</span> completaram a medida dos pecados contra a própria cabeça GPt 5:17.</p><p class=\"entry-text\"> B. Com acusativo (assim, no NT, 399 vezes [além de <span class=\"greek\">καθ</span>’ <span class=\"greek\">εἷς</span> e <span class=\"greek\">κατὰ εἷς</span>])</p><p class=\"entry-text\"> ① indicador de relação espacial</p><p class=\"entry-text\"> ⓐ referente à extensão no espaço: ao longo de, sobre, através de, em (Hom. et al.; OGI 90, 7 <span class=\"greek\">ἐκ τῶν κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">χώραν ἱερῶν</span>; PHib 82, 19; PTebt 5, 188; LXX; Just.; Mel., HE 4, 26, 5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:12</a>. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὅλην τ</span>. <span class=\"greek\">πόλιν</span> por toda a cidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:39</a> (cf. Diod S 4, 10, 6 <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὅλην τὴν Ἐλλάδα</span>). <span class=\"greek\">ἐγένετο λιμὸς κ</span>. <span class=\"greek\">τὴν χώραν ἐκείνην</span> 15:14. <span class=\"greek\">κ</span>. <span class=\"greek\">τὰς κώμας</span> 9:6. <span class=\"greek\">κ</span>. <span class=\"greek\">πόλεις καὶ κώμας</span> 13:22 (Appian., Maced. 9 §1 e 4 <span class=\"greek\">κ</span>. <span class=\"greek\">πόλεις</span>; Just., A I, 67, 3 <span class=\"greek\">κ</span>. <span class=\"greek\">πόλεις ἢ ἀγρούς</span>).—<span class=\"greek\">κ</span>. <span class=\"greek\">τόπους</span> de lugar em lugar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:11</a> (Theophr., <span class=\"greek\">περὶ σημ</span>. 1, 4 p. 389 W.; Cat. Cod. Astr. III 28, 11 <span class=\"greek\">ἐν μέρει τ</span>. <span class=\"greek\">ἀνατολῆς κ</span>. <span class=\"greek\">τόπους</span>, VIII/3, 186, 1 <span class=\"greek\">λιμὸς καὶ λοιμὸς καὶ σφαγαὶ κ</span>. <span class=\"greek\">τόπους</span>). <span class=\"greek\">οἱ ὄντες κ</span>. <span class=\"greek\">τὴν Ἰουδαίαν</span> os que se encontram na Judeia ou nela habitam <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:1</a>. <span class=\"greek\">διασπαρῆναι κ</span>. <span class=\"greek\">τὰς χώρας τῆς Ἰουδαίας</span> dispersar-se pelas regiões da Judeia 8:1. <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν οὖσαν ἐκκλησίαν</span> na congregação daquele lugar 13:1. <span class=\"greek\">τοῖς κ</span>. <span class=\"greek\">τὴν Ἀντιόχειαν καὶ Συρίαν καὶ Κιλικίαν ἀδελφοῖς</span> 15:23. <span class=\"greek\">τοὺς κ</span>. <span class=\"greek\">τὰ ἔθνη Ἰουδαίους</span> os judeus (dispersos) entre as nações 21:21. <span class=\"greek\">τοῖς κ</span>. <span class=\"greek\">τὸν νόμον γεγραμμένοις</span> ao longo da lei = na lei 24:14b. <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν ὁδόν</span> ao longo do caminho ou no caminho (Lucian, Catapl. 4; Jos., Ant. 8, 404) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:3</a>; 26:13. <span class=\"greek\">τὸ κ</span>. <span class=\"greek\">Κιλικίαν καὶ Παμφυλίαν πέλαγος</span> o mar junto à costa da Cilícia e da Panfília 27:5; mas a designação geográfica <span class=\"greek\">τὰ μέρη τ</span>. <span class=\"greek\">Λιβύης τῆς κ</span>. <span class=\"greek\">Κυρήνην</span> 2:10 provavelmente pertence à subacepção b: as regiões da Líbia em direção a Cirene.</p><p class=\"entry-text\"> ⓑ referente à extensão em direção a: rumo a, para, até <span class=\"greek\">ἐλθεῖν</span> (<span class=\"greek\">γίνεσθαι</span> v.l.) <span class=\"greek\">κ</span>. <span class=\"greek\">τὸν τόπον</span> aproximar-se do lugar (Jos., Vi. 283) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:32</a>. <span class=\"greek\">ἐλθόντες κ</span>. <span class=\"greek\">τὴν Μυσίαν</span> em direção à Mísia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:7</a>; cf. 27:7. <span class=\"greek\">πορεύεσθαι κ</span>. <span class=\"greek\">μεσημβρίαν</span> (veja <span class=\"greek\">μεσημβρία</span> 2) para o sul 8:26 (cf. Jos., Bell. 5, 505). <span class=\"greek\">κ</span>. <span class=\"greek\">σκοπὸν διώκειν</span> correr (ao longo do percurso) em direção à meta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:14</a>. <span class=\"greek\">λιμὴν βλέπων κ</span>. <span class=\"greek\">λίβα καὶ κ</span>. <span class=\"greek\">χῶρον</span> um porto aberto para sudoeste e noroeste <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:12</a> (veja <span class=\"greek\">βλέπω</span> 8).—<span class=\"greek\">κ</span>. <span class=\"greek\">πρόσωπον</span> à face (cf. Jos., Ant. 5, 205) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:11</a>. <span class=\"greek\">ἔχειν τινὰ κ</span>. <span class=\"greek\">πρόσωπον</span> encontrar alguém face a face (Thieme 19 apresenta referências para o emprego de <span class=\"greek\">κατὰ πρόσωπον</span> como fórmula jurídica) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:16</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">πρόσωπον ταπεινός</span> humilde quando pessoalmente presente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:1</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">πρόσωπόν τινος</span> na presença de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:13</a>. <span class=\"greek\">τὰ κ</span>. <span class=\"greek\">πρόσωπον</span> o que está diante dos olhos, isto é, o que é evidente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:7</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ὀφθαλμοὺς προγράφειν</span> representar diante dos olhos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:1</a>.</p><p class=\"entry-text\"> ⓒ referente a isolamento ou separação: por si, isoladamente (Thu. 1, 138, 6 <span class=\"greek\">οἱ καθ</span>’ <span class=\"greek\">ἑαυτοὺς Ἕλληνες</span> «os gregos, por si mesmos»; Polyb. 1, 24, 4; 5, 78, 3; 11, 17, 6; Diod S 13, 72, 8; Gen 30:40; 43:32; 2 Macc 13:13; Philo, Migr. Abr. 87; 90; Just., D. 4, 5 <span class=\"greek\">αὐτὴ καθ</span>’ <span class=\"greek\">ἑαυτήν γενομένη</span>; Tat. 13, 1 <span class=\"greek\">ἡ ψυχὴ καθ</span>’ <span class=\"greek\">ἑαυτήν</span>; Ath. 15, 2 <span class=\"greek\">ὁ πηλὸς καθ</span>’ <span class=\"greek\">ἑαυτόν</span>) <span class=\"greek\">ἔχειν τι καθ</span>’ <span class=\"greek\">ἑαυτόν</span> guardar algo para si <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:22</a> (cf. Jos., Ant. 2, 255; Heliod. 7, 16, 1). <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἑαυτὸν μένειν</span> viver sozinho, referente à residência particular de Paulo em Roma <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:16</a>. <span class=\"greek\">πίστις νεκρὰ καθ</span>’ <span class=\"greek\">ἑαυτήν</span> a fé por si só está morta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:17</a> (Simplicius in Epict. p. 3, 43 <span class=\"greek\">τὸ σῶμα καθ</span>’ <span class=\"greek\">αὑτὸ νεκρόν ἐστιν</span>). <span class=\"greek\">ἡ κατ</span>’ <span class=\"greek\">οἶκον ἐκκλησία</span> a congregação que se reúne na casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:19</a>. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἰδίαν</span>, veja <span class=\"greek\">ἴδιος</span> 5. <span class=\"greek\">κ</span>. <span class=\"greek\">μόνας</span> (Thu. 1, 32, 5; Menand., Epitr. 988 S. [658 Kö.], Fgm. 146 Kö. [158 Kock]; Polyb. 4, 15, 11; Diod S 4, 51, 16; BGU 813, 15 [veja APF 2, 1903, 97]; LXX) sozinho, por si mesmo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:18</a>; Hm 11:8 (aqui, bem como no trecho citado de BGU e na LXX, grafado como uma palavra só: <span class=\"greek\">καταμόνας</span>).</p><p class=\"entry-text\"> ⓓ referente a lugares considerados em sequência, uso distributivo com acusativo: um por um (Arrian., Anab. 4, 21, 10 <span class=\"greek\">κ</span>. <span class=\"greek\">σκηνήν</span>=tenda por tenda) ou de um lugar a outro: <span class=\"greek\">κατ</span>’ <span class=\"greek\">οἶκον</span> de casa em casa (PLond III, 904, 20 p. 125 [104 d.C.] <span class=\"greek\">ἡ κατ</span>’ <span class=\"greek\">οἰκίαν ἀπογραφή</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.46\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:46b</a>; 5:42 (ambos com referência às diversas reuniões ou congregações domésticas; menos provável é a tradução «em casa» da NRSV); cf. 20:20. De modo semelhante, o plural <span class=\"greek\">κ</span>. <span class=\"greek\">τοὺς οἴκους εἰσπορευόμενος</span> 8:3. <span class=\"greek\">κ</span>. <span class=\"greek\">τὰς συναγωγάς</span> 22:19. <span class=\"greek\">κ</span>. <span class=\"greek\">πόλιν</span> (Jos., Ant. 6, 73) de cidade em cidade IRo 9:3, mas em cada cidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:21</a>; 20:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:5</a>. Também <span class=\"greek\">κ</span>. <span class=\"greek\">πόλιν πᾶσαν</span> (cf. Herodian 1, 14, 9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:36</a>; <span class=\"greek\">κ</span>. <span class=\"greek\">πᾶσαν πόλιν</span> 20:23 D. <span class=\"greek\">κ</span>. <span class=\"greek\">πόλιν καὶ κώμην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:1</a>; cf. vs. 4.</p><p class=\"entry-text\"> ② indicador de relação temporal (Hdt. et al.; ins, pap, LXX, apolog.)</p><p class=\"entry-text\"> ⓐ em indicações definidas de tempo: em, no, durante (Hdt. 8, 17; Polemon Soph. B 43 Reader <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐκείνην τὴν ἡμέραν</span> «no decorrer daquele dia») <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἀρχάς</span> no princípio (cf. <span class=\"greek\">ἀρχή</span> 1b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:10</a> (Ps 101:26). <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν ἡμέραν τοῦ πειρασμοῦ</span> no dia da provação 3:8 (Ps 94:8.—Cf. Antig. Car. 173 <span class=\"greek\">κ</span>. <span class=\"greek\">τὸν σπόρου καιρόν</span>). <span class=\"greek\">νεκροῦ</span> … <span class=\"greek\">ἀνάστασιν κατ</span>’ <span class=\"greek\">αὐτὸν γεγονυῖαν ἱστορεῖ</span> (Papias) relata que ocorreu uma ressurreição dentre os mortos em sua época Papias (2, 9; assim, com nomes de pessoas, Hdt.; Just., D. 23, 1 <span class=\"greek\">τοῦ θεοῦ</span> … <span class=\"greek\">τοῦ κ</span>. <span class=\"greek\">τὸν Ἐνώχ</span>; Tat. 31, 2 <span class=\"greek\">Θεαγένης</span> … <span class=\"greek\">κ</span>. <span class=\"greek\">Καμβύσην γεγονώς</span>). Referente ao futuro: <span class=\"greek\">κ</span>. <span class=\"greek\">τὸν καιρὸν τοῦτον</span> naquele tempo, então <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:9</a> (Gen 18:10). Referente ao passado: <span class=\"greek\">κ</span>. <span class=\"greek\">ἐκεῖνον τὸν καιρόν</span> naquele tempo, então (2 Macc 3:5; TestJos 12:1; Jos., Ant. 8, 266; cf. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐκεῖνο τοῦ καιροῦ</span> Konon: 26 Fgm. 3 p. 191, 25 Jac.; Just., A I, 17, 2; 26, 3 al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:1</a>; 19:23. <span class=\"greek\">κ</span>. <span class=\"greek\">καιρόν</span> naquele tempo, então <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:6</a> (Just., D. 132, 1; cf. OGI 90, 28 <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὸ̔ν καιρόν</span>), a menos que <span class=\"greek\">καιρός</span> signifique aqui «tempo oportuno» (veja <span class=\"greek\">καιρός</span> 1b, final). <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὄναρ</span> (como <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὕπνον</span> Gen 20:6; Just., D 60, 5 <span class=\"greek\">κ</span>. <span class=\"greek\">τοὺς ὕπνους</span>) durante um sonho, em sonho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:20</a>; 2:12 (veja sob <span class=\"greek\">ὄναρ</span> as referências em inscrições).</p><p class=\"entry-text\"> ⓑ com indicações indefinidas de tempo: por volta de, aproximadamente <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ μεσονύκτιον</span> por volta da meia-noite <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:25</a>; cf. 27:27.—8:26 (veja <span class=\"greek\">μεσημβρία</span> 1).</p><p class=\"entry-text\"> ⓒ distributivamente (cf. 1d): período por período: <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἔτος</span> todos os anos (veja <span class=\"greek\">ἔτος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:41</a>. Também <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐνιαυτόν</span> (veja <span class=\"greek\">ἐνιαυτός</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:25</a>; 10:1, 3. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμέραν</span> diariamente, todos os dias (veja <span class=\"greek\">ἡμέρα</span> 2c) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:55</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:49</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:19</a>; 22:53; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.46\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:46f</a>; 3:2; 16:5; 17:11; 19:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:27</a>; 10:11. Também <span class=\"greek\">τὸ καθ</span>’ <span class=\"greek\">ἡμέραν</span> (veja <span class=\"greek\">ἡμέρα</span> 2c) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:3</a>; 19:47; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:11</a> v.l. <span class=\"greek\">ἡ ἐπίστασις ἡ καθ</span>’ <span class=\"greek\">ἡμέραν</span> (veja <span class=\"greek\">ἐπίστασις</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:28</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">πᾶσαν ἡμέραν</span> todos os dias (Jos., Ant. 6, 49) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:7</a>. Também <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἑκάστην ἡμέραν</span> (veja <span class=\"greek\">ἡμέρα</span> 2c) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:13</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">μίαν σαββάτου</span> no primeiro dia de cada semana <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:2</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">πᾶν σάββατον</span> todos os sábados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:27</a>; 15:21b; 18:4. <span class=\"greek\">κ</span>. <span class=\"greek\">μῆνα ἕκαστον</span> cada mês <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:2</a> (<span class=\"greek\">κ</span>. <span class=\"greek\">μῆνα</span> como em SIG 153, 65; POxy 275, 18; 2 Macc 6:7). <span class=\"greek\">κ</span>. <span class=\"greek\">ἑορτήν</span> em cada festa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:6</a>.</p><p class=\"entry-text\"> ③ indicador da divisão de um todo maior em partes individuais, de cada vez, detalhadamente; uso distributivo distinto das indicações de lugar (veja above 1d) e tempo (veja 2c)</p><p class=\"entry-text\"> ⓐ com numerais: <span class=\"greek\">κ</span>. <span class=\"greek\">δύο ἢ τὸ πλεῖστον τρεῖς</span> dois ou, no máximo, três de cada vez (isto é, em cada reunião, cf. <span class=\"greek\">ἀνὰ μέρος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:27</a> (Dio Chrys. 80 [30], 42 <span class=\"greek\">κ</span>. <span class=\"greek\">δύο καὶ τρεῖς</span>; Jos., Ant. 3, 142 <span class=\"greek\">κ</span>. <span class=\"greek\">ἕξ</span>; 5, 172 <span class=\"greek\">κ</span>. <span class=\"greek\">δύο καὶ τρεῖς</span>). <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἕνα</span> (quanto a esta e à seguinte expressão, veja <span class=\"greek\">εἷς</span> 5e) individualmente, um após o outro vs. 31. <span class=\"greek\">κ</span>. <span class=\"greek\">ἕνα λίθον</span> cada pedra individualmente Hs 9, 3, 5; <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἕνα λίθον</span> 9, 6, 3. <span class=\"greek\">κ</span>. <span class=\"greek\">ἓν ἕκαστον</span> um por um, detalhadamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:19</a>; 1 Cl 32:1 (Ath. 28, 4 <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἕκαστον</span>). <span class=\"greek\">εἷς καθ</span>’ <span class=\"greek\">εἷς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:9</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:5</a> (B-D-F §305; Rob. 460). <span class=\"greek\">κ</span>. <span class=\"greek\">ἑκατὸν καὶ κ</span>. <span class=\"greek\">πεντήκοντα</span> em grupos de cem e de cinquenta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:40</a>.</p><p class=\"entry-text\"> ⓑ <span class=\"greek\">περί τινος λέγειν κ</span>. <span class=\"greek\">μέρος</span> falar de alguma coisa detalhadamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:5</a> (veja <span class=\"greek\">μέρος</span> 1c). <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὄνομα</span> (cada um) pelo nome (<span class=\"greek\">ἀσπάζομαι</span> … <span class=\"greek\">τοὺς ἐνοίκους πάντες κα</span>[<span class=\"greek\">τ</span>’] <span class=\"greek\">ὄνομα</span> PTebt [século III d.C.] 422, 11–16; Jos., Vi. 86) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:3</a>; 3J 15 (cf. BGU 27, 18); ISm 13:2.</p><p class=\"entry-text\"> ④ indicador de intenção ou finalidade: com o propósito de, para (Thu. 6, 31, 1 <span class=\"greek\">κ</span>. <span class=\"greek\">θέαν ἥκειν</span>=olhar para alguma coisa; cf. Sb 7263, 6 [254 a.C.]; X., An. 3, 5, 2 <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἁρπαγὴν ἐσκεδασμένοι</span>; Arrian, Anab. 1, 17, 12; 4, 5, 1; 21, 9; 6, 17, 6; 26, 2; Lucian, Ver. Hist. 2, 29; Anton. Lib., Fab. 24, 1 <span class=\"greek\">Δημήτηρ ἐπῄει γῆν ἅπασαν κ</span>. <span class=\"greek\">ζήτησιν τῆς θυγατρός</span>; 38; Jdth 11:19) <span class=\"greek\">κ</span>. <span class=\"greek\">τὸν καθαρισμὸν τῶν Ἰουδαίων</span> para a purificação ritual dos judeus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:6</a>. <span class=\"greek\">κατὰ ἀτιμίαν λέγω</span> para minha vergonha <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:21</a> (cf. Jos., Ant. 3, 268 <span class=\"greek\">κ</span>. <span class=\"greek\">τιμὴν τ</span>. <span class=\"greek\">θεοῦ τοῦτο ποιῶν</span>). <span class=\"greek\">ἀπόστολος</span> … <span class=\"greek\">κ</span>. <span class=\"greek\">πίστιν</span> … <span class=\"greek\">καὶ ἐπίγνωσιν</span> apóstolo … para a fé … e o conhecimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:1</a> (mas a acepção «de acordo com» também é provável).</p><p class=\"entry-text\"> ⑤ indicador de norma de semelhança ou homogeneidade: segundo, de acordo com, em conformidade com</p><p class=\"entry-text\"> ⓐ para introduzir a norma que rege alguma coisa</p><p class=\"entry-text\"> <span class=\"greek\">α</span>. referente à norma da lei etc. (OGI 56, 33; Mitt-Wilck., I/2, 352, 11 <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ κελευσθέντα</span> [como em Just., D. 78, 7]; POxy 37 II, 8) <span class=\"greek\">κ</span>. <span class=\"greek\">τὸν νόμον</span> (Jos., Ant. 14, 173; 15, 51; Just., D. 10, 1 al.; Ath. 31, 1; <span class=\"greek\">κ</span>. <span class=\"greek\">τοὺς νόμους Ἀρεοπαγείτης</span>, carta de Marco Aurélio: ZPE 8, ’71, 169, ln. 27) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:31</a>; 19:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:5</a>. <span class=\"greek\">τὰ κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">νόμον</span> o que deve ser feito segundo a lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:39</a> (cf. EpArist 32). <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ ὡρισμένον</span> de acordo com o que foi determinado 22:22. Cf. 1:9; 2:24, 27, 42; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:2</a>; 22:3. <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ εὐαγγέλιόν μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:16</a>; 16:25a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:8</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ εἰρημένον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:18</a> (cf. Ath. 28, 1 <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ προειρημένα</span>). <span class=\"greek\">κ</span>. <span class=\"greek\">τὰς γραφάς</span> (Just., D. 82, 4; cf. Paus. 6, 21, 10 <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ ἔπη</span>=segundo os poemas épicos; Just., A I, 32, 14 <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ λόγιον</span>, D. 67, 1 <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν προφητείαν ταύτην</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:3</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:8</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν παράδοσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:5</a> (Tat. 39, 1 <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν Ἑλλήνων παράδοσιν</span>).—<span class=\"greek\">κ</span>. <span class=\"greek\">λόγον</span> como se deseja (exemplos em Dssm., B 209 [não consta em BS]; também PEleph 13, 1; 3 Macc 3:14) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:14</a> (embora também seja provável a subacepção 5b<span class=\"greek\">β</span> abaixo).—Também pode ocorrer simplesmente com o acusativo da pessoa segundo cuja vontade, preferência ou modo algo acontece <span class=\"greek\">κ</span>. <span class=\"greek\">θεόν</span> (cf. Socrat., Ep. 14, 5 <span class=\"greek\">κ</span>. <span class=\"greek\">θεόν</span>; 26, 2; Nicol. Dam.: 90 Fgm. 4 p. 332, 1 Jac. e Appian, Bell. Civ. 2, 84 §352 <span class=\"greek\">κ</span>. <span class=\"greek\">δαίμονα</span>; Jos., Ant. 4, 143 <span class=\"greek\">ὁ κ</span>. <span class=\"greek\">τοῦτον</span>[=<span class=\"greek\">θεόν</span>] <span class=\"greek\">βίος</span>; Just., D. 5, 1 <span class=\"greek\">κ</span>. <span class=\"greek\">τινας</span> … <span class=\"greek\">Πλατωνικούς</span>; Tat. 1, 3 <span class=\"greek\">κ</span>. … <span class=\"greek\">τὸν κωμικόν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:9</a>–11; <span class=\"greek\">κ</span>. <span class=\"greek\">Χριστὸν Ἰ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:5</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">κύριον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:17</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:15</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">Ἕλληνας</span> à maneira dos gregos, isto é, dos politeístas PtK 2, p. 14, 1; 7. <span class=\"greek\">κ</span>. <span class=\"greek\">Ἰουδαίους</span> ln. 25.</p><p class=\"entry-text\"> <span class=\"greek\">β</span>. a norma segundo a qual se profere um julgamento ou se concedem recompensas ou punições <span class=\"greek\">ἀποδοῦναι τινι κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">πρᾶξιν</span> or <span class=\"greek\">ἔργα αὐτοῦ</span> (Ps 61:13; Pr 24:12; Just., A I, 12, 1; 17, 4 al.; <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἀξίαν τῶν πράξεων</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:23</a>. <span class=\"greek\">μισθὸν λήμψεται κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἴδιον κόπον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:8</a>. <span class=\"greek\">κρίνειν κ</span>. <span class=\"greek\">τι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:24</a>; 8:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:17</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:2</a>.</p><p class=\"entry-text\"> <span class=\"greek\">γ</span>. referente a um padrão de qualquer outra espécie <span class=\"greek\">κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">χρόνον ὸ̔ν ἠκρίβωσεν</span> segundo o tempo que havia verificado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:16</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">πίστιν ὑμῶν</span> segundo a vossa fé 9:29. <span class=\"greek\">κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">δύναμιν</span> segundo a sua capacidade 25:15 (Just., D. 139, 4; Tat. 12, 3; cf. Just., A II, 13, 6 <span class=\"greek\">κ</span>. <span class=\"greek\">δύναμιν</span>). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:38</a>; 2:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:4</a>; 10:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:7</a>. <span class=\"greek\">ἀνὴρ κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">καρδίαν μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:22</a> (<span class=\"greek\">καρδία</span> 1b<span class=\"greek\">ε</span>).</p><p class=\"entry-text\"> <span class=\"greek\">δ</span>. Frequentemente a norma é simultaneamente a causa, de modo que «conforme» e «por causa de» se confundem: <span class=\"greek\">οἱ κ</span>. <span class=\"greek\">πρόθεσιν κλητοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:28</a>. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐπιταγὴν θεοῦ</span> 16:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:3</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἀποκάλυψιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:3</a> (Just., D. 78, 2). <span class=\"greek\">οἱ καθ</span>’ <span class=\"greek\">ὑπομονὴν ἔργου ἀγαθοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:7</a>. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐκλογήν</span> 11:5 (Just., D. 49, 1). Cf. <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν βουλήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:11</a> (Just., A I, 63, 16 al.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:16</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τί γνώσομαι τοῦτο</span>; por que meio saberei isto? (cf. Gen 15:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:18</a>.—Em lugar de «de acordo com», <span class=\"greek\">κ</span>. pode significar simplesmente «por causa de», «em consequência de», «com base em» (Ael. Aristid. 46 p. 219 D.: <span class=\"greek\">κ</span>. <span class=\"greek\">τοὺς νόμους</span>; Jos., Ant. 1, 259; 278; Just., A I, 54, 1 <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐνέργειαν τῶν φαύλων δαιμόνων</span>; Ath. 7, 1 <span class=\"greek\">κ</span>. <span class=\"greek\">συμπάθειαν τῆς παρὰ τοῦ θεοῦ πνοῆς</span>; 32, 1 <span class=\"greek\">κ</span>. <span class=\"greek\">χρησμόν</span>). <span class=\"greek\">κ</span>. <span class=\"greek\">πᾶσαν αἰτίαν</span> por toda e qualquer razão (<span class=\"greek\">αἰτία</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:3</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἀποκάλυψιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:2</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:8</a> (<span class=\"greek\">κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">πνεῦμα</span> = <span class=\"greek\">διὰ τοῦ πν</span>.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:5</a>; 4:22b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:5</a>; <span class=\"greek\">κ</span>. <span class=\"greek\">ἀνάγκην</span> Phlm 14 (Ar. 1, 2; 4, 2 al.; Just., A I, 30, 1; 61, 10; Ath. 24, 2); IPol 1:3. <span class=\"greek\">ὁ κ</span>. <span class=\"greek\">τὸ πολὺ αὐτοῦ ἔλεος ἀναγεννήσας ἡμᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:3</a>.—<span class=\"greek\">καθ</span>’ <span class=\"greek\">ὅσον</span> (Thu. 4, 18, 4) na medida em que, visto que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:3</a>. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὅσον</span> … , <span class=\"greek\">κ</span>. <span class=\"greek\">τοσοῦτο</span> na medida em que …, nessa mesma medida (Lysias 31, 8; Galen, De Dignosc. Puls. 3, 2, VIII 892 K.) 7:20, 22.</p><p class=\"entry-text\"> ⓑ como perífrase para expressar igualdade, semelhança ou exemplo: de acordo com, assim como, semelhantemente a (TestJob 32:6 <span class=\"greek\">τίς γὰρ κ</span>. <span class=\"greek\">σε ἐν μέσῳ τῶν τέκνων σου</span>; Tat. 25, 1 <span class=\"greek\">κ</span>. … <span class=\"greek\">τὸν Πρωτέα</span> como Proteu; escólio sobre Nicandro, Ther. 50: as ovelhas não são animais de carga <span class=\"greek\">κ</span>. <span class=\"greek\">τοὺς ὄνους</span>=como os jumentos são).</p><p class=\"entry-text\"> <span class=\"greek\">α</span>. <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ ἔργα αὐτῶν μὴ ποιεῖτε</span> não façais como eles fazem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:3</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">Ἰσαάκ</span> assim como Isaque <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:28</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">θεὸν κτισθείς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:24</a> (Synes., Prov. 2, 2 p. 118c <span class=\"greek\">κ</span>. <span class=\"greek\">θεόν</span>=como um deus). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:10</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τὸν τύπον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:5</a> (Ex 25:40; Mel., P. 58, 424 [<span class=\"greek\">νόμον</span> v.l.]). Cf. 5:6 (Ps 109:4); 8:9 (Jer 38: 32); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:9</a>.—<span class=\"greek\">κ</span>. <span class=\"greek\">τὰ αὐτά</span> da mesma maneira (OGI 56, 66; PEleph 2, 6; 1 Macc 8:27; 12:2; Just., D. 1, 2; 3, 5; 113, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:23</a>, 26; 17:30; Dg 3:1. Por outro lado, o singular <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ αὐτό</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:1</a> significa «juntamente» (contrato de casamento PEleph 1, 5 [século IV a.C.] <span class=\"greek\">εἶναι ἡμᾶς κ</span>. <span class=\"greek\">ταὐτό</span>; 1 Km 11:11). <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὸ̔ν τρόπον</span> assim como (2 Macc 6:20; 4 Macc 14:17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:11</a>; 27:25. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὅσον</span> … , <span class=\"greek\">οὕτως</span> assim como …, também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:27</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">πάντα τρόπον</span> de todas as maneiras (PSI 520, 16 [250 a.C.]; PCairZen 631, 2; 3 Macc 3:24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:2</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">μηδένα τρόπον</span> (PMagd 14, 9 [221 a.C.]; PRein 7, 31; 3 Macc 4:13; 4 Macc 4:24; Just., D. 35, 7; veja Reader, Polemo 262) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:3</a>. Cf. Johannessohn, Kasus, 1910, 82. <span class=\"greek\">κατά</span> com acusativo serve, em geral,</p><p class=\"entry-text\"> <span class=\"greek\">β</span>. para indicar a natureza, espécie, particularidade ou características de alguma coisa (frequentemente como perífrase do advérbio; por exemplo, Antíoco de Siracusa [século V a.C.]: 555 Fgm. 12 Jac. <span class=\"greek\">κ</span>. <span class=\"greek\">μῖσος</span>=por ódio, cheio de ódio) <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐξουσίαν</span> com autoridade ou poder <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:27</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">συγκυρίαν</span> por acaso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:31</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἄγνοιαν</span> sem saber <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:17</a> (veja <span class=\"greek\">ἄγνοια</span> 2a). <span class=\"greek\">κ</span>. <span class=\"greek\">ἄνθρωπον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:3</a> al. (veja Straub 15; Aeschyl., Th. 425; <span class=\"greek\">ἄνθρωπος</span> 2b). <span class=\"greek\">κ</span>. <span class=\"greek\">κράτος</span> poderosamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:20</a> (<span class=\"greek\">κράτος</span> 1a). <span class=\"greek\">κ</span>. <span class=\"greek\">λόγον</span> razoavelmente, corretamente (Pla.; Polyb. 1, 62, 4; 5; 5, 110, 10; Jos., Ant. 13, 195; PYale 42, 24 [12 jan. 229 a.C.]) 18:14 (mas veja acima 5a<span class=\"greek\">α</span>). <span class=\"greek\">λέγειν τι κ</span>. <span class=\"greek\">συγγνώμην οὐ κατ</span>’ <span class=\"greek\">ἐπιταγήν</span> dizer alguma coisa por concessão, não por ordem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:6</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:8</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τάξιν</span> de maneira ordeira <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.40\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:40</a> (<span class=\"greek\">τάξις</span> 2). <span class=\"greek\">κατ</span>’ <span class=\"greek\">ὀφθαλμοδουλίαν</span> servindo apenas sob vigilância <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:6</a>. <span class=\"greek\">μηδὲν κατ</span>’ <span class=\"greek\">ἐριθείαν μηδὲ κ</span>. <span class=\"greek\">κενοδοξίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:3</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ζῆλος</span> zelosamente 3:6a, a menos que a passagem inteira pertença à acepção 6 abaixo. <span class=\"greek\">κ</span>. <span class=\"greek\">σάρκα</span> no plano físico <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:12f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:17</a>; também 5:16ab, se aqui <span class=\"greek\">κ</span>. <span class=\"greek\">ς</span>. se ligar a <span class=\"greek\">οἴδαμεν</span> ou <span class=\"greek\">ἐγνώκαμεν</span> (conforme entendem Bachmann, JWeiss, H-D Wendle e Sickenberger; veja 7a below). <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὑπερβολήν</span> (PTebt 42, 5f [aprox. 114 a.C.] <span class=\"greek\">ἠδικημένος καθ</span>’ <span class=\"greek\">ὑπερβολὴν ὑπὸ</span>, <span class=\"greek\">Ἁρμιύσιος</span>; 4 Macc 3:18) além de toda medida, sem comparação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:17</a>. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὁμοιότητα</span> (Aristot.; Gen 1:12; Philo, Fug. 51; Tat. 12, 4 <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ ὅμοιον αὐτῇ</span>) de maneira semelhante <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:15b</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">μικρόν</span> resumidamente B 1:5 (<span class=\"greek\">μικρός</span> 1e<span class=\"greek\">γ</span>).</p><p class=\"entry-text\"> ⑥ designando relação com alguma coisa: quanto a, em relação a <span class=\"greek\">κ</span>. <span class=\"greek\">σάρκα</span> quanto à carne, fisicamente, por descendência humana <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:3</a>; 4:1; 9:3, 5 (Ar. 15, 7 <span class=\"greek\">κ</span>. <span class=\"greek\">σάρκα</span> … <span class=\"greek\">κ</span>. <span class=\"greek\">ψυχήν</span>; Just., D. 43, 7 <span class=\"greek\">ἐν τῷ γένει τῷ κ</span>. <span class=\"greek\">σάρκα τοῦ Ἀβραάμ</span> al.). <span class=\"greek\">κ</span>. <span class=\"greek\">τὸν ἔσω ἄνθρωπον</span> 7:22 (cf. POxy 904, 6 <span class=\"greek\">πληγαῖς κατακοπτόμενον κ</span>. <span class=\"greek\">τὸ σῶμα</span>). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:4</a>; 11:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:5</a>, 6b (quanto ao versículo 6a, veja 5b<span class=\"greek\">β</span> acima); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:9b</a>. <span class=\"greek\">τὰ κ</span>. <span class=\"greek\">τινα</span> (Hdt. 7, 148; Diod S 1, 10, 73; Aelian, VH 2, 20; PEleph 13, 3; POxy 120, 14; Tob 10:9; 1 Esdr 9:17; 2 Macc 3:40; 9:3 al.) a situação, as circunstâncias de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:22</a> (cf. PEleph 13, 3 <span class=\"greek\">τὰ κ</span>. <span class=\"greek\">σε</span>; Just., A I, 61, 13 <span class=\"greek\">τὰ κ</span>. <span class=\"greek\">τὸν Ἰησοῦν πάντα</span>, D. 102, 2 <span class=\"greek\">τὰ κ</span>. <span class=\"greek\">αὐτόν</span>; Ath. 24, 4 <span class=\"greek\">τὸ κ</span>. <span class=\"greek\">τοὺς ἀγγέλους</span>); 25:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:7</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">πάντα</span> em todos os aspectos (já em Tucídides 4, 81, 3; Sb 4324, 3; 5761, 22; SIG 834, 7; Gen 24:1; Wsd 19:22; 2 Macc 1:17; 3 Macc 5:42; JosAs 1:7; Just., A II, 4, 4, D. 35, 8 al.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:20</a>, 22a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:17</a> (Artem. 1, 13 <span class=\"greek\">αὐτῷ ὅμοιον κ</span>. <span class=\"greek\">π</span>.); 4:15a.</p><p class=\"entry-text\"> ⑦ Às vezes, a expressão com <span class=\"greek\">κατά</span>, que soaria pesada se traduzida literalmente por «tal e tal», «em consonância com» ou «de acordo com», é mais bem vertida mediante um adjetivo, pronome possessivo ou construção genitiva para expressar a perspectiva segundo a qual algo é percebido ou compreendido. Assim, na tradução, funciona como</p><p class=\"entry-text\"> ⓐ um adjetivo (Synes., Kingdom 4 p. 4d <span class=\"greek\">τὰ κατ</span>’ <span class=\"greek\">ἀρετὴν ἔργα</span> isto é, as obras conformes ao que é excelente = obras virtuosas; PHib 27, 42 <span class=\"greek\">ταῖς κ</span>. <span class=\"greek\">σελήνην ἡμέραις</span>; 4 Macc 5:18 <span class=\"greek\">κ</span>. <span class=\"greek\">ἀλήθειαν</span>=<span class=\"greek\">ἀληθής</span>; Just., A I, 2, 1 <span class=\"greek\">τοὺς κ</span>. <span class=\"greek\">ἀλήθειαν εὐσεβεῖς</span>; Tat. 26, 2 <span class=\"greek\">τῆς κ</span>. <span class=\"greek\">ἀλήθειαν σοφίας</span>) <span class=\"greek\">οἱ κ</span>. <span class=\"greek\">φύσιν κλάδοι</span> os ramos naturais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:21</a>. <span class=\"greek\">ἡ κατ</span>’ <span class=\"greek\">εὐσέβειαν διδασκαλία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:3</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:1b</a>. <span class=\"greek\">οἱ κ</span>. <span class=\"greek\">σάρκα κύριοι</span> os senhores terrenos (num jogo de palavras que antecipa o <span class=\"greek\">κύριος</span> que está nos céus, vs. 9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:5</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:16b</a>, caso (veja 5b<span class=\"greek\">β</span> above) <span class=\"greek\">κ</span>. <span class=\"greek\">ς</span>. se ligue a <span class=\"greek\">Χριστόν</span> (conforme entende a maioria, inclusive Ltzm.): um Cristo físico, Cristo na carne, nas suas relações terrenas (<span class=\"greek\">σάρξ</span> 5). Correspondentemente, no versículo 16a, <span class=\"greek\">κ</span>. <span class=\"greek\">ς</span>. seria ligado a <span class=\"greek\">οὐδένα</span>: ninguém considerado meramente como ser físico.—JMartyn, JKnox Festschr., ’67, 269–87.</p><p class=\"entry-text\"> ⓑ um pronome possessivo, mas com força restritiva (Demosth. 2, 27 <span class=\"greek\">τὰ καθ</span>’ <span class=\"greek\">ὑμᾶς ἐλλείμματα</span> [isto é, em contraste com as atividades de outros: «vossos próprios»]; Aelian, VH 2, 42 <span class=\"greek\">ἡ κατ</span>’ <span class=\"greek\">αὐτὸν ἀρετή</span>; 3, 36; OGI 168, 17 <span class=\"greek\">παραγεγονότες εἰς τοὺς καθ</span>’ <span class=\"greek\">ὑμᾶς τόπους</span>; SIG 646, 6; 807, 15 al.; UPZ 20, 9 [século II a.C.] <span class=\"greek\">ἐπὶ τῆς καθ</span>’ <span class=\"greek\">ἡμᾶς λειτουργίας</span>; PTebt 24, 64; 2 Macc 4:21; Tat. 42, 1 <span class=\"greek\">τίς ὁ θεὸς καὶ τίς ἡ κατ</span>’ <span class=\"greek\">αὐτὸν ποίησις</span>; Mel., HE 4, 26, 7 <span class=\"greek\">ἡ καθ</span>’ <span class=\"greek\">ἡμᾶς φιλοσοφία</span>) <span class=\"greek\">τῶν καθ</span>’ <span class=\"greek\">ὑμᾶς ποιητῶν τινες</span> alguns dos vossos próprios poetas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:28</a>. <span class=\"greek\">ἡ καθ</span>’ <span class=\"greek\">ὑμᾶς πίστις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:15</a>. <span class=\"greek\">ὁ καθ</span>’ <span class=\"greek\">ὑμᾶς νόμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:15</a>. <span class=\"greek\">τὸ κατ</span>’ <span class=\"greek\">ἐμὲ πρόθυμον</span> minha disposição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:15</a>.</p><p class=\"entry-text\"> ⓒ um genitivo com substantivo (Polyb. 3, 113, 1 <span class=\"greek\">ἡ κ</span>. <span class=\"greek\">τὸν ἥλιον ἀνατολή</span>; 2, 48, 2; 3, 8, 1 al.; Diod S 14, 12 <span class=\"greek\">ἡ κ</span>. <span class=\"greek\">τὸν τύραννον ὠμότης</span>; Dionys. Hal. 2, 1; SIG 873, 5 <span class=\"greek\">τῆς κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">μυστήρια τελετῆς</span>; 569, 22; 783, 20; PTebt 5, 25; PLond III, 1164k, 20 p. 167 [212 d.C.] <span class=\"greek\">ὑπὸ τοῦ κ</span>. <span class=\"greek\">πατέρα μου ἀνεψιοῦ</span>) <span class=\"greek\">τὰ κ</span>. <span class=\"greek\">Ἰουδαίους ἔθη</span> os costumes dos judeus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:3</a> (Tat. 12, 5 <span class=\"greek\">τῇ κ</span>. <span class=\"greek\">Βαβυλωνίους προγνωστικῇ</span>; 34, 2 <span class=\"greek\">ἡ κ</span>. <span class=\"greek\">τὸν Ἀριστόδημον πλαστική</span>). Cf. 27:2. <span class=\"greek\">ἡ κ</span>. <span class=\"greek\">πίστιν δικαιοσύνη</span> a justiça da fé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:7</a>. <span class=\"greek\">ἡ κατ</span>’ <span class=\"greek\">ἐκλογὴν πρόθεσις</span> propósito da eleição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:11</a>.—Aqui pertencem também os títulos dos Evangelhos <span class=\"greek\">εὐαγγέλιον κατὰ Ματθαῖον</span> etc., nos quais <span class=\"greek\">κατά</span> é igualmente perífrase de um genitivo (cf. JLydus, De Mag. 3, 46 p. 136, 10 Wünsch <span class=\"greek\">τῆς κ</span>. <span class=\"greek\">Λουκανὸν συγγραφῆς</span>; Herodian 2, 9, 4 referente a uma autobiografia <span class=\"greek\">ἐν τῷ καθ</span>’ <span class=\"greek\">αὑτὸν βίῳ</span>; Jos., C. Ap. 1, 18 <span class=\"greek\">τ</span>. <span class=\"greek\">καθ</span>’ <span class=\"greek\">αὐτὸν ἱστορίαν</span>; 2 Macc 2:13. Cf. B-D-F §163; 224, 2; Zahn, Einleitung §49; BBacon, Why ‘According to Mt’? Exp., 8th ser., 16, 1920, 289–310).—Quanto à perífrase do genitivo mediante <span class=\"greek\">κατά</span>, veja Rudberg (<span class=\"greek\">ἀνά</span> beg.) com muitos exemplos desde Platão. Mas já ocorre em Tucídides 6, 16, 5 <span class=\"greek\">ἐν τῷ κατ</span>’ <span class=\"greek\">αὐτοὺς βίῳ</span>.—M-M. DELG. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταβαίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">imperfeito <span class=\"greek\">κατέβαινον</span>; futuro <span class=\"greek\">καταβήσομαι</span>; 2º aoristo <span class=\"greek\">κατέβην</span>, imperativo <span class=\"greek\">κατάβηθι</span> e <span class=\"greek\">κατάβα</span> (Diog. L. 2, 41) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:30</a> v.l.; perfeito <span class=\"greek\">καταβέβηκα</span> (desde Homero; em geral, «descer»)</p><p class=\"entry-text\"> ① mover-se para baixo, vir ou ir para baixo, descer, literalmente</p><p class=\"entry-text\"> ⓐ referente a pessoas:</p><p class=\"entry-text\"> <span class=\"greek\">α</span>. com indicação do lugar de onde alguém vem ou desce: <span class=\"greek\">ἀπό τινος</span> (Pind., N. 6, 51; X., Cyr. 5, 5, 6; Ael. Aristid. 51, 22 K.=27 p. 538 D.: <span class=\"greek\">ἀπὸ τ</span>. <span class=\"greek\">ὄρους</span>; Gen 38:1; Ex 32:15 <span class=\"greek\">ἀπὸ τ</span>. <span class=\"greek\">ὄρους</span>; 4 Km 1:16; Na 3:7 v.l.; Ezk 47:1; JosAs 5:11 <span class=\"greek\">ἀπὸ τ</span>. <span class=\"greek\">ἅρματος</span>; Jos., Ant. 6, 108) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:9</a> v.l.; <span class=\"greek\">ἀπὸ ὀρινῆς</span> GJs 18:1 (pap; 19:1 codd.). Descer de uma cruz (Chariton 4, 3, 6 <span class=\"greek\">κατέβαινε τοῦ σταυροῦ</span>, depois da ordem <span class=\"greek\">κατάβηθι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:40</a>, 42; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:30</a>, 32. Sair de um barco (cf. Ezk 27:29) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:29</a>. Com <span class=\"greek\">ἔκ τινος</span>: <span class=\"greek\">ἐκ τ</span>. <span class=\"greek\">ὄρους</span> (Il. 13, 17; X., An. 7, 4, 12; Ex 19:14; 32:1; Dt 9:15; 10:5; Josh 2:23) 17:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:9</a>. <span class=\"greek\">ἐντεῦθεν</span> 1 Cl 53:2 (Dt 9:12); GJs 4:2b. Em emprego absoluto, embora o contexto indique claramente de onde se desce <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:15</a> (veja <span class=\"greek\">δ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:5f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:10</a>; 23:10; B 4:8; 14:3 (as duas últimas ocorrências citam Ex 32:7, com acréscimo de <span class=\"greek\">ἐντεῦθεν</span>); MPol 7:2. Referente a alguém em posição elevada GJs 1:4; 4:3; 16:2. Seguido de infinitivo (Gen. 11:5; 43:20; Ex 3:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:31</a>. <span class=\"greek\">καταβὰς ἔστη</span> 6:17.—Ir, voltar, regressar <span class=\"greek\">κατέβησαν εὐφραινόμενοι</span> GJs 6:3 voltaram (para casa) com alegria. Aqui a preposição funciona como advérbio auxiliar (cf. Gen 43:13; Jer 43:14).</p><p class=\"entry-text\"> <span class=\"greek\">β</span>. como na LXX (correspondente ao hebraico <span class=\"hebrew\" lang=\"he\" dir=\"rtl\">יָרַד</span> 3 Km 22:2; 4 Km 8:29; 10:13 al.) referente à saída de Jerusalém ou da Palestina: <span class=\"greek\">ἀπὸ Ἱεροσολύμων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:30</a> (cf. 1 Macc 16:14); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:7</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:1</a>, 22. Referente ao templo GJs 5:1 veja sob <span class=\"greek\">δ</span>. Com referências geográficas em geral (frequente na LXX; TestSim 4:3 <span class=\"greek\">εἰς Αἴγυπτον</span>; Jos., Vi. 68 <span class=\"greek\">εἰς Τιβεριάδα</span>) <span class=\"greek\">εἰς Αἴγυπτον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:15</a> (também <span class=\"greek\">κ</span>. <span class=\"greek\">ἐκεῖ</span> Did., Gen. 227, 5). <span class=\"greek\">εἰς Ἀντιόχειαν</span> 18:22.—14:25; 16:8; 25:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:12</a>. Em uso absoluto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.47\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:47</a>, 49, 51; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:15</a>; 10:20.</p><p class=\"entry-text\"> <span class=\"greek\">γ</span>. referente à descida do céu (Maximus Tyr. 11, 12e <span class=\"greek\">κ</span>. <span class=\"greek\">ἐκ τ</span>. <span class=\"greek\">θεοῦ μέχρι γῆς</span>) <span class=\"greek\">ἀπὸ τοῦ οὐρανοῦ</span> (Diogenes, Ep. 38, 1; Da 4:13, 23 Theod.; Philo, Migr. Abr. 185; Ar. 15, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:16</a>. <span class=\"greek\">ἐξ οὐρανοῦ</span> (Chariton 6, 3, 4 <span class=\"greek\">τὶς ἐξ οὐρ</span>. <span class=\"greek\">καταβέβηκε</span>. Referente a coisas Dt 28:24; 4 Km 1:10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:13</a> (quanto ao contraste <span class=\"greek\">ἀναβαίνω εἰς τ</span>. <span class=\"greek\">οὐρ</span>. … <span class=\"greek\">καταβαίνω</span>, cf. Pr 30:4; PGM 4, 546f; cf. Iren. 1, 9, 3 [Harv. I 84, 5]); 6:33, 41f, 50f, 58; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:1</a>; 18:1; 20:1. Abs. (Aristóbulo em Eus., PE 8, 10, 13 [=Holladay p. 144, linha 94]; PGM 4, 3024; 36, 299; Orig., C. Cels. 4, 3, 2; Did., Gen. 110, 17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:34</a> (Ex 3:8); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.51\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:10</a>.</p><p class=\"entry-text\"> <span class=\"greek\">δ</span>. com indicação do lugar para o qual alguém vai ou desce <span class=\"greek\">εἰς τ</span>. <span class=\"greek\">οἰκίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:15</a> v.l. (cf. <span class=\"greek\">α</span> above). <span class=\"greek\">εἰς τὸν παράδεισον αὐτῆς</span> para o jardim dela GJs 2:4; <span class=\"greek\">εἰς τὴν ἄβυσσον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:7</a>. <span class=\"greek\">εἰς ᾅδου</span> (Ar. 11, 3; Diod S 4, 25, 4 e Artem. 2, 55 com <span class=\"greek\">ἀναβαίνειν ἐξ ᾅδου</span>) 1 Cl 51:4 (Num 16:30; Ps 54:16). <span class=\"greek\">εἰς τὰ κατώτερα μέρη τῆς γῆς</span> (s. <span class=\"greek\">κατώτερος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:9</a>. Especialmente referente ao batismo <span class=\"greek\">κ</span>. <span class=\"greek\">εἰς</span> (<span class=\"greek\">τὸ</span>) <span class=\"greek\">ὕδωρ</span> descer às águas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:38</a>; B 11:8, 11; Hm 4, 3, 1; Hs 9, 16, 4 e 6a; cf. 6b. <span class=\"greek\">εἰς τὸν οἶκον αὐτοῦ</span> (do templo) para casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:14</a>; semelhantemente, <span class=\"greek\">ἐκ τοῦ ναοῦ</span> … <span class=\"greek\">καὶ ἥκει ἐν τῷ οἴκῳ αὐτοῦ</span> GJs 5:1; cf. 8:1. <span class=\"greek\">ἐπὶ τὴν θάλασσαν</span> (X., Ages. 1, 18; cf. Gen 24:16, 45) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:16</a>. <span class=\"greek\">ἐπὶ τὸν λιμένα</span> AcPl Ha 5, 15; <span class=\"greek\">πρὸς τοὺς ἄνδρας</span> (cf. 1 Km 10:8; 4 Km 1:15; 1 Macc 10:71) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:21</a>; cf. 14:11 <span class=\"greek\">θεοὶ</span> … <span class=\"greek\">κατέβησαν πρὸς ἡμᾶς</span>. <span class=\"greek\">ἄγγελος</span> … <span class=\"greek\">κυρίου κατέβη πρὸς Ἰωακείμ</span> GJs 4:2a. <span class=\"greek\">ἄγγελος κατέβαινεν ἐν τ</span>. <span class=\"greek\">κολυμβήθρᾳ</span> para dentro do tanque <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:4</a> (cf. Judg 7:9f B <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν τ</span>. <span class=\"greek\">παρεμβολῇ</span>). Referente à descida do diabo: <span class=\"greek\">πρός τινα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:12</a> (cf. Philo, Gig. 12 [<span class=\"greek\">ψυχαὶ</span>] <span class=\"greek\">πρὸς σώματα κατέβησαν</span>).</p><p class=\"entry-text\"> ⓑ referente a coisas etc.: um lençol do céu (cf. SibOr 2, 20) descer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:11</a>; 11:5. Toda boa dádiva desce <span class=\"greek\">ἀπὸ τοῦ πατρὸς τῶν φώτων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:17</a>. Referente à Nova Jerusalém <span class=\"greek\">κ</span>. <span class=\"greek\">ἐκ τ</span>. <span class=\"greek\">οὐρανοῦ ἀπὸ τοῦ θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:12</a>; 21:2, 10. Referente ao Espírito Santo no batismo de Jesus: <span class=\"greek\">καταβ</span>. <span class=\"greek\">εἰς αὐτόν</span> descer e entrar nele <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:10</a>. <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτόν</span> sobre ele <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:32f</a>. Referente à chuva (cf. Ps 71:6; Is 55:10; Jos., Ant. 2, 343) cair <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:25</a>, 27. Referente a uma tempestade descer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:23</a>. Referente ao fogo cair <span class=\"greek\">ἀπὸ τοῦ οὐρανοῦ</span> (cf. Jos., Ant. 2, 343) 9:54. <span class=\"greek\">ἐκ τοῦ οὐρανοῦ εἰς τὴν γῆν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:13</a>. <span class=\"greek\">ἐκ τ</span>. <span class=\"greek\">οὐρανοῦ</span> (4 Km 1:10, 14; 2 Macc 2:10) 20:9. Referente ao granizo <span class=\"greek\">ἐκ τοῦ οὐρανοῦ ἐπί τινα</span> cair do céu sobre alguém 16:21. Referente às gotas de sangue <span class=\"greek\">ἐπὶ τὴν γῆν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:44</a> (cf. Sir 35:15 <span class=\"greek\">δάκρυα ἐπὶ σιαγόνα</span>). Referente a uma estrada conduzir para longe <span class=\"greek\">ἀπὸ Ἰερουσαλήμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:26</a>.</p><p class=\"entry-text\"> ② sofrer humilhação, extensão figurada da acepção 1: ser rebaixado <span class=\"greek\">ἕως ᾅδου</span> (cf. Is 14:11, 15. <span class=\"greek\">ἕως</span> as Ps 106:26; ApcEsdr 4:32 p. 29, 9 Tdf.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:15</a> (em ambas, <span class=\"greek\">καταβιβασθήσῃ</span> é variante textual; veja <span class=\"greek\">καταβιβάζω</span>).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταβάλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro <span class=\"greek\">καταβαλῶ</span> LXX; 2º aoristo <span class=\"greek\">κατέβαλον</span>; perfeito, 3ª pessoa do singular <span class=\"greek\">καταβέβληκε</span> Pr 7:26. Na voz passiva: particípio aoristo <span class=\"greek\">καταβληθείς</span> 4 Macc 12:1; particípio perfeito <span class=\"greek\">καταβεβλημένη</span> Pr 25:28 (veja <span class=\"greek\">βάλλω</span>; desde Homero; inscrições, papiros, LXX, En; TestSol 23:1; TestJob 18:1; ApcEsdr 5:12 p. 30, 6 [<span class=\"greek\">τὸν σπόρον</span> … <span class=\"greek\">ἐν τῇ γῇ</span>; cf. Ath. 33, 1]; EpArist, Philo, Joseph., Just., Tat., Ath.).</p><p class=\"entry-text\"> ① golpear com força suficiente para derrubar: lançar por terra, prostrar, na voz ativa e passiva (X., Cyr. 1, 3, 14 et al.—«desistir, cessar» Tat. 1, 2; 9, 3; Ath. 21, 3) <span class=\"greek\">τινά</span>, alguém (Diod S 14, 17, 10; Appian, Liby. 111, §527; Lucian, Dial. Deor. 14, 2; Philo, Agr. 120; PsSol, TestSol, Just.; Tat. 20, 1) na voz passiva, <span class=\"greek\">καταβαλλόμενοι ἀλλ</span>’ <span class=\"greek\">οὐκ ἀπολλύμενοι</span>, abatidos, mas não destruídos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:9</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:10</a> v.l.</p><p class=\"entry-text\"> ② assentar alguma coisa de modo duradouro, fundar, lançar (um fundamento), <span class=\"greek\">θεμέλιον</span>, na voz média (Dionys. Hal. 3, 69 <span class=\"greek\">τοὺς θεμελίους</span>; Porphyr., Abst. 8, 10; Jos., Ant. 11, 93; 15, 391; cf. 2 Macc 2:13 <span class=\"greek\">βιβλιοθήκην</span>; EpArist 104) em sentido figurado (assim, por exemplo, sobre a fundação de uma escola filosófica Plut., Mor. 329a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:1</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταβαρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">1º aoristo <span class=\"greek\">κατεβάρησα</span> (veja <span class=\"greek\">βαρέω</span>; Polyb.; Diod S 19, 24, 5 e outros; Cyr. Ins. linha 11; POxy 487, 10) sobrecarregar, ser um peso para <span class=\"greek\">τινά</span>, alguém (Appian, Bell. Civ. 5, 67 §283) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:16</a> (variante textual <span class=\"greek\">κατενάρκησα</span>). Em uso absoluto, <span class=\"greek\">αἱ ἁμαρτίαι ὑμῶν κατεβάρησαν</span> vossos pecados pesaram sobre vós (o contexto subentende <span class=\"greek\">ὑμᾶς</span>) Hs 9, 28, 6.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταβαρύνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">passivo, aoristo subjuntivo, 1ª pessoa do plural <span class=\"greek\">καταβαρυνθῶμεν</span> 2 Km 13:25 (veja artigo precedente; Teofrasto e outros; LXX) pesar sobre, sobrecarregar, oprimir <span class=\"greek\">τὴν ζωήν</span> tornar difícil a vida de alguém (cf. <span class=\"greek\">τὸν βίον</span> Antip. em Estobeu 4, 22, 25 vol. IV 511, 7 H.) Hm 12, 6, 2. Na voz passiva (Herm. Wr. 2, 9), acerca dos olhos <span class=\"greek\">ἦσαν καταβαρυνόμενοι</span> estavam pesados = fecharam-se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:40</a>.—DELG sob o verbete <span class=\"greek\">βαρύς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάβασις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">βαίνω</span>; Heródoto e outros; inscrições, papiros, LXX; AscIs 3, 13; Philo, Joseph.) caminho de descida, descida (Polyb. 3, 54, 5; Diod S 4, 21, 2; 14, 28, 5; Jos., Bell. 2, 547), também encosta, declive (Ps.-Demetr., Eloc. §248; Josh 10:11) <span class=\"greek\">ἐγγίζειν πρὸς τῇ κ</span>. <span class=\"greek\">τοῦ ὄρους τῶν ἐλαιῶν</span> aproximar-se da encosta do monte das Oliveiras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:37</a>.—DELG sob o verbete <span class=\"greek\">βαίνω</span>. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταβῇ</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">veja <span class=\"greek\">καταβαίνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταβιβάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(causativo de <span class=\"greek\">καταβαίνω</span>) futuro <span class=\"greek\">καταβιβάσω</span> LXX; aoristo <span class=\"greek\">κατεβίβασα</span> LXX. Na voz passiva: futuro <span class=\"greek\">καταβιβασθήσομαι</span>; imperativo aoristo <span class=\"greek\">καταβιβάσθητι</span> Ezk 31:18 (<span class=\"greek\">βιβάζω</span> «fazer subir»; Hdt. et al.; PLond II, 130, 105f p. 136; LXX; TestSol 10:35 C <span class=\"greek\">τὴν σελήνην</span>) fazer descer, impelir para baixo <span class=\"greek\">τινά</span>, fazer alguém descer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:33</a> D. Na voz passiva (cf. Fílon, Deus Imm. 120) <span class=\"greek\">ἕως ᾅδου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:23</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:15</a> v.l. em ambas as passagens, em lugar de <span class=\"greek\">καταβήσῃ</span> (veja <span class=\"greek\">καταβαίνω</span> 2).—DELG sob o verbete <span class=\"greek\">βαίνω</span> 3 p. 156. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταβοάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro, 3ª pessoa do singular <span class=\"greek\">καταβοήσεται</span> Dt 24:15; 1º aoristo <span class=\"greek\">κατεβόησα</span> LXX (Heródoto e outros; OGI 669, 5; 51; PSI 440, 19; 551, 2; 4; 6; LXX; Jos., Bell. 3, 410, Ant. 3, 307) clamar em voz alta, gritar, formular acusações, queixar-se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:13</a> D.—DELG sob o verbete <span class=\"greek\">βοή</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταβολή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">καταβάλλω</span>; Hipócrates, Demóstenes e outros; inscrições, papiros, 2 Macc 2:29; AssMos Fgm. a=Tromp p. 272; EpArist, Philo, Joseph.; Just., D. 102, 4 <span class=\"greek\">τῇ ἐπὶ τοῦ πύργου καταβολῇ</span> [veja <span class=\"greek\">καταβάλλω</span> 2]; Ath., R. 17 p. 69, 6).</p><p class=\"entry-text\"> ① o ato de assentar algo, com a implicação de fornecer uma base para alguma coisa: fundação. À ideia de fundar se associa facilmente a acepção «começo» (Jos., Bell. 2, 260 <span class=\"greek\">ἀποστάσεως καταβολή</span>) <span class=\"greek\">τ</span>. <span class=\"greek\">καταβολὴν τ</span>. <span class=\"greek\">στάσεως ποιεῖν</span> ser responsável por iniciar a dissensão (cf. Polyb. 13, 6, 2 <span class=\"greek\">καταβολὴν ἐποιεῖτο τυραννίδος</span>) 1 Cl 57:1. Especialmente <span class=\"greek\">καταβολὴ κόσμου</span> (Plut., Mor. 956a <span class=\"greek\">ἅμα τῇ πρώτῃ καταβολῇ τ</span>. <span class=\"greek\">ἀνθρώπων</span>): <span class=\"greek\">ἀπὸ καταβολῆς κόσμου</span> desde a fundação do mundo (Theoph., Ant. 3, 26 [p. 258, 27]; em sentido diferente, Políbio 1, 36, 8; 24, 8, 9; Diod S 12, 32, 2—os três com <span class=\"greek\">ἐκ καταβολῆς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:35</a>; 25:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:3</a>; 9:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:8</a>; 17:8; B 5:5. <span class=\"greek\">πρὸ καταβολῆς κόσμου</span> (AssMos Fgm. a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:20</a>.—OHofius, ZNW 62, ’71, 123–38. Também em emprego absoluto (sem <span class=\"greek\">κόσμου</span>, veja <span class=\"greek\">κόσμος</span> 3; cf. EpArist 129) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:35</a> v.l. Esta pode ser a acepção de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:11</a>, onde se diz a respeito de Sara <span class=\"greek\">δύναμιν εἰς καταβολὴν σπέρματος ἔλαβεν</span> ela recebeu a capacidade de estabelecer uma descendência (veja nota marginal da NRSV). But</p><p class=\"entry-text\"> ② <span class=\"greek\">κ</span>., termo técnico para a semeadura de sementes, empregado para a geração de descendentes (<span class=\"greek\">τοῦ σπέρματος</span> [<span class=\"greek\">εἰς γῆν ἢ μήτραν</span> M. Ant. 4, 36]: Plut., Mor. 320b <span class=\"greek\">σπορὰ κ</span>. <span class=\"greek\">καταβολή</span> referente à geração de Rômulo por Ares e Sílvia; 905e; Ps.-Lucian, Amor. 19; Galen, Aphorism. 4, 1, XVII/2, 653 K.; cf. Philo, Op. M. 132; Epict. 1, 13, 3; Herm. Wr. 9, 6; Ath., R. 17 p. 69, 6 <span class=\"greek\">σπερμάτων καταβολήν</span>; veja Field, Notes 232). Se essa acepção estiver correta para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:11</a>, provavelmente existe algum erro no texto, pois essa expressão não poderia ser empregada a respeito de Sara, mas apenas de Abraão (por exemplo, <span class=\"greek\">αὐτῇ Σάρρᾳ</span>=«juntamente com Sara» é a leitura da margem de W-H.; Riggenbach; Michel; B-D-F §194, 1. Esse uso do dativo ocorre em Tucídides, Xenofonte e outros, também em Diod S 20, 76, 1; Appian, Samn. 7 §2; Polyaenus 6, 18, 2; 7, 15, 3; 8, 28; Theod. Prodr. 6, 148 H. <span class=\"greek\">αὐτῇ Ῥοδάνῃ</span>). Windisch, manual, comentário ao trecho; veja <span class=\"greek\">αἷμα</span> 1a.—MBlack, An Aramaic Approach3, ’67, 83–89.—DELG sob o verbete <span class=\"greek\">βάλλω</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταβραβεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">βραβεύω</span>; Demosth., 21, 93; Vett. Val. 344, 30; Sb 4512 B, 57 [século II a.C.]) «decidir contra» (como árbitro) e, portanto, privar de prêmio, condenar <span class=\"greek\">τινά</span> (Didymus [século I a.C./século I d.C.] p. 179 MSchmidt; veja Field, Notes 196f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:18</a>.—DELG sob o verbete <span class=\"greek\">βραβεύς</span>, «árbitro, juiz». M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγγελεύς, έως, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja artigo seguinte; OGI 456, 10 [século I a.C.] «anunciador dos jogos»; IG XII/8, 190, 39f [século I d.C.]; Pel.-Leg. 18, 21) anunciador, pregador <span class=\"greek\">ξένων δαιμονίων</span> de divindades estrangeiras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:18</a>.—DELG sob o verbete <span class=\"greek\">ἄγγελος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγγέλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">imperfeito <span class=\"greek\">κατήγγελλον</span>; 1º aoristo <span class=\"greek\">κατήγγειλα</span>; perfeito <span class=\"greek\">κατήγγελκα</span>. Na voz passiva: 2º aoristo <span class=\"greek\">κατηγγέλην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:13</a>; particípio perfeito <span class=\"greek\">κατηγγελμένος</span> (Just.). (Desde Xenofonte, An. 2, 5, 38; inscrições [por exemplo, SIG 797, 6]; papiros; 2 Macc; Philo, Op. M. 106; Joseph., Just., Tat.; frequentemente empregado acerca de decretos públicos) tornar conhecido publicamente, com ampla divulgação: proclamar, anunciar</p><p class=\"entry-text\"> ⓐ com uma coisa como objeto <span class=\"greek\">τὶ</span>, alguma coisa: o evangelho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:14</a>; costumes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:21</a>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμέρας ταύτας</span> 3:24 (Jos., Ant. 3, 206 <span class=\"greek\">ἑορτήν</span>). <span class=\"greek\">τὸν θάνατον τοῦ κυρίου καταγγέλλετε</span> anunciais (pela celebração da Ceia, mais do que pelas palavras) a morte do Senhor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:26</a>. <span class=\"greek\">τὸν λόγον τοῦ θεοῦ ἐν ταῖς συναγωγαῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:5</a>; cf. 15:36. Na voz passiva, 17:13. <span class=\"greek\">ἐν τῷ Ἰησοῦ τὴν ἀνάστασιν τὴν ἐκ νεκρῶν</span> anunciar na pessoa de Jesus a ressurreição dentre os mortos 4:2. Na voz passiva, <span class=\"greek\">ἡ πίστις ὑμῶν καταγγέλλεται ἐν ὅλῳ τῷ κόσμῳ</span>, vossa fé é conhecida em todo o mundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:8</a>; cf. Pol 1:2.—<span class=\"greek\">τινί τι</span>, alguma coisa a alguém (Philo, Aet. M. 68; Jos., Ant. 2, 15) <span class=\"greek\">ἄφεσιν ἁμαρτιῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:38</a>; <span class=\"greek\">ὁδὸν σωτηρίας</span> 16:17. <span class=\"greek\">τὸ μυστήριον</span> (<span class=\"greek\">μαρτύριον</span> v.l.) <span class=\"greek\">τοῦ θεοῦ</span> o propósito secreto de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:1</a>. <span class=\"greek\">φῶς τῷ τε λαῷ καὶ τοῖς ἔθνεσιν</span> anunciar luz ao povo (de Israel) e aos gentios <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:23</a>; cf. 17:23. <span class=\"greek\">εἴς τι</span>: <span class=\"greek\">εἰς τὸ εὐαγγέλιον</span> dirigir a proclamação ao evangelho, isto é, prefigurá-lo IPhld 5:2.</p><p class=\"entry-text\"> ⓑ com objeto pessoal: <span class=\"greek\">τινά</span>, alguém (Iren. 1, 19, 1 [Harv. I 175, 4]) <span class=\"greek\">τὸν Χριστόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:17</a>; cf. vs. 18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:28</a> (Just., D. 7, 3). <span class=\"greek\">τινά τινι</span>, alguém a outra pessoa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:3</a> (Iren. 1, 20, 2 [Harv. I 178, 10]). <span class=\"greek\">οἱ προφῆται κ</span>. <span class=\"greek\">εἰς αὐτόν</span> os profetas dirigiram sua proclamação a ele (Jesus) IPhld 9:2.—DELG sob o verbete <span class=\"greek\">ἄγγελος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγέλαστος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja artigo seguinte e <span class=\"greek\">γελάω</span>; Aristófanes, Heródoto e outros; Dio Chrys. 57 [74], 12; Ael. Aristid. 43, 1 K.=1 p. 1 D.; Celsus 6, 78; Wsd 17:8; Philo; Jos., C. Ap. 1, 254) ridículo Dg 4:1.—DELG sob o verbete <span class=\"greek\">γελάω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγελάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">imperfeito <span class=\"greek\">κατεγέλων</span>; 1º aoristo <span class=\"greek\">κατεγέλασα</span>; futuro na voz média <span class=\"greek\">καταγελάσομαι</span> LXX; futuro passivo <span class=\"greek\">καταγελασθήσομαι</span> LXX (veja artigo anterior; Ésquilo, Heródoto e posteriores; SIG 1168, 122 [século III a.C.]; BGU 814, 21; POxy 3313, 17 [século II d.C.]; LXX; TestSol 4, 5f D; TestJob 32:11; Just.; Tat. 10, 2) rir de, ridicularizar <span class=\"greek\">τινός</span>, alguém (Hdt. 5, 68 al.; Achilles Tat. 1, 1, 13 [ed. SGaselee ’47]; Philo, Omn. Prob. Lib. 156; Jos., Ant. 5, 144; <span class=\"greek\">ἡμῶν</span> Just., A I, 58, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:53</a>; 1 Cl 56:11 (Job 5:22); 2 Cl 13:4.—DELG sob o verbete <span class=\"greek\">γελάω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγίνομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">γίνομαι</span>; Demóstenes, Teles e outros; inscrições, papiros, LXX; Manetho: 609 Fgm. 8, 77 Jac. [em Josefo, C. Ap. 1, 77]) <span class=\"greek\">ἔν τινι</span>, ocupar-se com, estar absorvido por algo (Polyb. 31, 29, 6; Diog. L. 6, 70) <span class=\"greek\">ὁ νοῦς αὐτῶν περὶ τὴν πρᾶξιν καταγίνεται</span> sua mente está ocupada com seus próprios assuntos Hm 10, 1, 5.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταγινώσκω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro, 3ª pessoa do singular <span class=\"greek\">καταγνώσεται</span> Pr 28:11; 2º aoristo <span class=\"greek\">κατέγνων</span> LXX. Na voz passiva: futuro, 3ª pessoa do singular <span class=\"greek\">καταγνωσθήσεται</span> Sir 19:5; infinitivo aoristo <span class=\"greek\">καταγνωσθῆναι</span>; particípio perfeito passivo <span class=\"greek\">κατεγνωσμένος</span> (TestBenj 6:7) (veja <span class=\"greek\">κατάγνωσις</span>; Aeschyl., Hdt.+ em diversos sentidos) condenar, declarar culpado (Thu. 6, 60, 4; Lysias 1, 32 al.; PYale 42, 24; referente ao juízo desfavorável de Deus Jos., Bell. 7, 327) <span class=\"greek\">τινός</span>, alguém ou alguma coisa (Ps.-Pla., Demod. 382e; OGI 691, 2; POxy 1062, 14; Dt 25:1; Philo, Omn. Prob. Lib. 79; Jos., Ant. 4, 5) <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμῶν ἡ καρδία</span> 1J 3:20 (TestGad 5:3 <span class=\"greek\">οὐχ ὑπ</span>’ <span class=\"greek\">ἄλλου καταγινωσκόμενος ἀλλ</span>’ <span class=\"greek\">ὑπὸ τ</span>. <span class=\"greek\">ἰδίας καρδίας</span>; Sir 14:2; TestBenj 6:7 <span class=\"greek\">μὴ καταγνωσθῆναι ὑπὸ τῶν ἀνθρώπων</span>, <span class=\"greek\">ὁμοίως καὶ ὑπὸ τοῦ θεοῦ</span>); vs. 21 o objeto deve ser subentendido a partir do contexto anterior; semelhantemente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:2</a> D; <span class=\"greek\">τ</span>. <span class=\"greek\">ἀπάτης τοῦ κόσμου</span> condenar o engano do mundo Dg 10:7.—<span class=\"greek\">κατεγνωσμένος ἦν</span> ele estava condenado (por suas próprias ações ou opiniões manifestadas publicamente, cf. Diod S 34+35 Fgm. 29 <span class=\"greek\">κατεγνώσθη</span>=foi condenado [por seu ato ultrajante ou por sua opinião manifestada publicamente], isto é, o amigo desleal de Graco; Diog. L. 6, 33 <span class=\"greek\">καταγινωσκομένους</span> [por suas opiniões públicas]; Jos., Bell. 2, 135) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:11</a>.—FMozley, Exp. 8th Ser. IV 1912, 143–46.—DELG sob o verbete <span class=\"greek\">γιγνώσκω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0187-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάγνυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro <span class=\"greek\">κατεάξω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:20</a>, 2ª pessoa do singular <span class=\"greek\">κατάξεις</span> Hab 3:12; 1º aoristo <span class=\"greek\">κατέαξα</span>, particípio <span class=\"greek\">κατάξας</span>, imperativo <span class=\"greek\">κάταξον</span> LXX; 2º aoristo passivo <span class=\"greek\">κατεάγην</span> (W-S. §12, 2; 15 sob <span class=\"greek\">ἄγνυμι</span>; B-D-F §66, 2; 101 sob <span class=\"greek\">ἄγνυμι</span>; Mlt-H. 189; 226 sob <span class=\"greek\">ἄγνυμι</span>), 3ª pessoa do singular <span class=\"greek\">κατεάχθη</span> Jer 31:25 (<span class=\"greek\">ἄγνυμι</span> «quebrar, despedaçar»; Hom.+; inscrições, papiros, LXX, Philo; Jos., Bell. 6, 402, Ant. 5, 225) quebrar uma cana <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:20</a>; membros do corpo (Menand., Epitr. 1062 S.=704 Kö.; Prov. Aesopi 10 P. <span class=\"greek\">λόγος καλὸς ὀστοῦν κατεάξει</span>) <span class=\"greek\">τὰ σκέλη</span> as pernas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:31</a>, 32, 33 (Eus., HE 5, 21, 3 <span class=\"greek\">κατεάγνυται τὰ σκέλη</span>; Philostorg. 3, 27 <span class=\"greek\">Ἀέτιον ἀμφοῖν τοῖν σκέλοιν κατεαγῆναι</span>.—Pauly-W. IV 1731. Cf. <span class=\"greek\">σκελοκοπέω</span> e veja <span class=\"greek\">σκέλος</span>). DELG sob o verbete <span class=\"greek\">ἄγνυμι</span>. M-M.</p></section></article>\n"};
